@startuml

class Customer {
  + name : string
  + dateOfBirth : date
  + address : string
  + taxCode : string
}

class Broker {
  + brokerId : int
  + name : string
  + contactInfo : string
}

class Contract {
  + contractNumber : int
  + signingDate : date
  + insuredAmount : double
  + policyType : string
}

class Policy {
  + policyId : int
  + policyName : string
  + description : string
}

class Claim {
  + claimId : int
  + claimDate : date
  + status : string
}

class Estimator {
  + estimatorId : int
  + name : string
  + expertiseArea : string
}

class CompensationDecision {
  + decisionId : int
  + compensationAmount : double
  + paymentStatus : string
}

Customer "1" -- "1..*" Broker
Broker "1" -- "0..*" Contract
Customer "1" -- "0..*" Contract
Contract "1" -- "1" Policy
Claim "1" -- "1" Contract
Estimator "1" -- "0..*" Claim
Claim "1" -- "0..*" Estimator
CompensationDecision "1" -- "1" Claim

@enduml

